      { title: 'Matrix Row Sums', diff: 'EASY', desc: 'Given R x C matrix, print sum of each row on separate lines.', test: [{in: '2 3\n1 2 3\n4 5 6\n', out: '6\n15\n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        for(int i=0; i<r; i++) {\n            int sum = 0;\n            for(int j=0; j<c; j++) sum += sc.nextInt();\n            System.out.println(sum);\n        }\n    }\n}' },
      { title: 'Transpose of Matrix', diff: 'MEDIUM', desc: 'Print transpose of R x C matrix.', test: [{in: '2 3\n1 2 3\n4 5 6\n', out: '1 4 \n2 5 \n3 6 \n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        int[][] m = new int[r][c];\n        for(int i=0; i<r; i++) for(int j=0; j<c; j++) m[i][j] = sc.nextInt();\n        for(int j=0; j<c; j++) {\n            for(int i=0; i<r; i++) System.out.print(m[i][j] + " ");\n            System.out.println();\n        }\n    }\n}' },
      { title: 'Spiral Traversal of Matrix', diff: 'MEDIUM', desc: 'Print elements of R x C matrix in spiral order.', test: [{in: '3 3\n1 2 3\n4 5 6\n7 8 9\n', out: '1 2 3 6 9 8 7 4 5 \n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        int[][] m = new int[r][c];\n        for(int i=0; i<r; i++) for(int j=0; j<c; j++) m[i][j] = sc.nextInt();\n        int top = 0, bottom = r - 1, left = 0, right = c - 1;\n        while(top <= bottom && left <= right) {\n            for(int j=left; j<=right; j++) System.out.print(m[top][j] + " ");\n            top++;\n            for(int i=top; i<=bottom; i++) System.out.print(m[i][right] + " ");\n            right--;\n            if(top <= bottom) { for(int j=right; j>=left; j--) System.out.print(m[bottom][j] + " "); bottom--; }\n            if(left <= right) { for(int i=bottom; i>=top; i--) System.out.print(m[i][left] + " "); left++; }\n        }\n        System.out.println();\n    }\n}' },
      { title: 'Rotate Matrix 90 Degrees Clockwise', diff: 'HARD', desc: 'Rotate N x N matrix 90 degrees clockwise in-place.', test: [{in: '2\n1 2\n3 4\n', out: '3 1 \n4 2 \n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] m = new int[n][n];\n        for(int i=0; i<n; i++) for(int j=0; j<n; j++) m[i][j] = sc.nextInt();\n        for(int j=0; j<n; j++) {\n            for(int i=n-1; i>=0; i--) System.out.print(m[i][j] + " ");\n            System.out.println();\n        }\n    }\n}' }
