      { title: 'Two Sum II (Sorted Array)', diff: 'MEDIUM', desc: 'Find 1-based indices of two numbers in sorted array that add up to target K.', test: [{in: '4 9\n2 7 11 15\n', out: '1 2\n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), target = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        int l = 0, r = n - 1;\n        while(l < r) {\n            int sum = a[l] + a[r];\n            if (sum == target) { System.out.println((l+1) + " " + (r+1)); break; }\n            else if (sum < target) l++;\n            else r--;\n        }\n    }\n}' },
      { title: 'Max Consecutive Ones', diff: 'EASY', desc: 'Find max consecutive 1s in a binary array.', test: [{in: '6\n1 1 0 1 1 1\n', out: '3\n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int max = 0, curr = 0;\n        for(int i=0; i<n; i++) {\n            if (sc.nextInt() == 1) { curr++; max = Math.max(max, curr); }\n            else curr = 0;\n        }\n        System.out.println(max);\n    }\n}' },
      { title: 'Container With Most Water', diff: 'MEDIUM', desc: 'Given N heights, find max area of water a container can store.', test: [{in: '5\n1 8 6 2 5\n', out: '24\n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] h = new int[n]; for(int i=0; i<n; i++) h[i] = sc.nextInt();\n        int l = 0, r = n - 1, maxArea = 0;\n        while(l < r) {\n            int area = Math.min(h[l], h[r]) * (r - l);\n            maxArea = Math.max(maxArea, area);\n            if (h[l] < h[r]) l++; else r--;\n        }\n        System.out.println(maxArea);\n    }\n}' }
