      { title: 'Sliding Window Maximum', diff: 'HARD', desc: 'Find maximum in each sliding window of size K.', test: [{in: '8 3\n1 3 -1 -3 5 3 6 7\n', out: '3 3 5 5 6 7 \n'}], starter: 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=0; i<=n-k; i++) {\n            int max = a[i];\n            for(int j=1; j<k; j++) max = Math.max(max, a[i+j]);\n            System.out.print(max + " ");\n        }\n        System.out.println();\n    }\n}' }
