function escapeSql(str) {
  if (!str) return 'NULL';
  return "'" + str.replace(/'/g, "''").replace(/\\/g, "\\\\").replace(/\n/g, "\\n") + "'";
}

function escapeJsonSql(obj) {
  const jsonStr = JSON.stringify(obj);
  return "'" + jsonStr.replace(/'/g, "''") + "'";
}

let sqlLines = [
  "-- Flyway Migration V5: Seed 5-8 practice questions per DSA class (classes 1-80)",
  "-- Auto-generated comprehensive problem set"
];

for (let classNum = 1; classNum <= 80; classNum++) {
  const classHex = String(classNum).padStart(4, '0');
  const classSessionId = `d0000001-${classHex}-4000-8000-000000000001`;

  // Find template group
  const templateGroup = topicTemplates.find(t => classNum >= t.start && classNum <= t.end) || topicTemplates[0];

  templateGroup.questions.forEach((q, idx) => {
    const qIndexHex = String(idx + 1).padStart(4, '0');
    const questionId = `e0000005-${classHex}-${qIndexHex}-000000000000`;
    
    // Test cases format
    const testCasesObj = q.test.map((t, tidx) => ({
      input: t.in,
      expected_output: t.out,
      hidden: tidx > 0
    }));

    const examplesObj = q.test.map(t => ({
      input: t.in.trim(),
      output: t.out.trim(),
      explanation: `Example case for ${q.title}`
    }));

    const constraintsObj = [
      "Input size N <= 100000",
      "Time Limit: 2.0s",
      "Memory Limit: 256MB"
    ];

    const tagsObj = [templateGroup.category.toLowerCase().replace(/[^a-z0-9]/g, '-'), q.diff.toLowerCase()];

    const sql = `INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES (${escapeSql(questionId)}, ${escapeSql(classSessionId)}, ${escapeSql(q.title + ' (Class ' + classNum + ')')}, ${escapeSql(q.diff)}, ${escapeSql(q.desc)}, ${escapeJsonSql(constraintsObj)}, ${escapeJsonSql(examplesObj)}, ${escapeSql(q.starter)}, ${escapeJsonSql(testCasesObj)}, ${escapeJsonSql(tagsObj)}, ${idx + 1});`;

    sqlLines.push(sql);
  });
}

const outputPath = path.join(__dirname, '../backend/src/main/resources/db/migration/V5__seed_dsa_questions.sql');
fs.writeFileSync(outputPath, sqlLines.join('\n\n'), 'utf8');
console.log(`Successfully generated V5__seed_dsa_questions.sql with ${sqlLines.length - 2} question insertions at ${outputPath}!`);
